#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// Float pow kernel: pow(base, exp) = exp(log(base) * exp)
template <typename T>
class KernelForeachPowListFloat {
public:
    __aicore__ inline KernelForeachPowListFloat() {}

    __aicore__ inline void Init(GM_ADDR base, GM_ADDR exp, GM_ADDR out,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            baseGm.SetGlobalBuffer((__gm__ T *)base + offset, formerLength);
            expGm.SetGlobalBuffer((__gm__ T *)exp + offset, formerLength);
            outGm.SetGlobalBuffer((__gm__ T *)out + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            baseGm.SetGlobalBuffer((__gm__ T *)base + offset, tailLength);
            expGm.SetGlobalBuffer((__gm__ T *)exp + offset, tailLength);
            outGm.SetGlobalBuffer((__gm__ T *)out + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) == sizeof(half)) {
            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf4, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf5, tileLength * sizeof(float));
        } else {
            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> baseLocal = inQueueX.AllocTensor<T>();
        AscendC::LocalTensor<T> expLocal = inQueueY.AllocTensor<T>();

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(baseLocal, baseGm[progress * this->tileLength], copyParams, padParams);
        AscendC::DataCopyPad(expLocal, expGm[progress * this->tileLength], copyParams, padParams);

        inQueueX.EnQue(baseLocal);
        inQueueY.EnQue(expLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> baseLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> expLocal = inQueueY.DeQue<T>();
        AscendC::LocalTensor<T> outLocal = outQueueZ.AllocTensor<T>();

        if constexpr (sizeof(T) == sizeof(half)) {
            // FP16/BF16: Cast to FP32 -> compute -> Cast back
            AscendC::LocalTensor<float> baseFp32 = tmpBuf1.Get<float>();
            AscendC::LocalTensor<float> expFp32 = tmpBuf2.Get<float>();
            AscendC::LocalTensor<float> logLocal = tmpBuf3.Get<float>();
            AscendC::LocalTensor<float> mulLocal = tmpBuf4.Get<float>();
            AscendC::LocalTensor<float> outFp32 = tmpBuf5.Get<float>();

            AscendC::Cast(baseFp32, baseLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(expFp32, expLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

            // pow(base, exp) = exp(log(base) * exp)
            AscendC::Ln(logLocal, baseFp32, curTileLength);
            AscendC::Mul(mulLocal, logLocal, expFp32, curTileLength);
            AscendC::Exp(outFp32, mulLocal, curTileLength);

            AscendC::Cast(outLocal, outFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        } else {
            // FP32: direct compute
            AscendC::LocalTensor<float> logLocal = tmpBuf1.Get<float>();
            AscendC::LocalTensor<float> mulLocal = tmpBuf2.Get<float>();

            // pow(base, exp) = exp(log(base) * exp)
            AscendC::Ln(logLocal, baseLocal, curTileLength);
            AscendC::Mul(mulLocal, logLocal, expLocal, curTileLength);
            AscendC::Exp(outLocal, mulLocal, curTileLength);
        }

        outQueueZ.EnQue<T>(outLocal);
        inQueueX.FreeTensor(baseLocal);
        inQueueY.FreeTensor(expLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> outLocal = outQueueZ.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(outGm[progress * this->tileLength], outLocal, copyParams);
        outQueueZ.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf3;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf4;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf5;
    AscendC::GlobalTensor<T> baseGm;
    AscendC::GlobalTensor<T> expGm;
    AscendC::GlobalTensor<T> outGm;
    int64_t blockLength;
    int64_t tileLength;
};

// Integer pow kernel: compute base^exp using repeated multiplication
class KernelForeachPowListInt {
public:
    __aicore__ inline KernelForeachPowListInt() {}

    __aicore__ inline void Init(GM_ADDR base, GM_ADDR exp, GM_ADDR out,
