namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

void foreach_pow_list_tensor_fp(const at::Tensor &base,
                                 const at::Tensor &exp,
                                 at::Tensor &out)
{
    int64_t totalLength = base.numel();
    if (totalLength == 0) {
        return;
    }

    int64_t dtypeSize = base.element_size();

    // ---- Get hardware params ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block level tiling ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB level tiling ----
    int64_t bufferCoefficient = (dtypeSize == 2) ? 32 : 32;
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) { tileLength = alignElements; }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(foreach_pow_list, blockDim,
                    base, exp, out,
                    formerNum, formerLength, tailLength, tileLength, dtypeSize);
}

std::vector<at::Tensor> foreach_pow_list(const std::vector<at::Tensor> &x1,
                                          const std::vector<at::Tensor> &x2)
{
    TORCH_CHECK(x1.size() == x2.size(),
                "foreach_pow_list: x1 and x2 must have the same length");
    TORCH_CHECK(x1.size() > 0,
                "foreach_pow_list: input lists must not be empty");

    std::vector<at::Tensor> out;
    out.reserve(x1.size());

    for (size_t i = 0; i < x1.size(); ++i) {
        TORCH_CHECK(x1[i].scalar_type() == x2[i].scalar_type(),
                    "foreach_pow_list: x1[", i, "] and x2[", i,
                    "] must have the same dtype");
        TORCH_CHECK(x1[i].numel() == x2[i].numel(),
                    "foreach_pow_list: x1[", i, "] and x2[", i,
                    "] must have the same number of elements");

        at::Tensor output = at::empty_like(x1[i]);

        auto dtype = x1[i].scalar_type();
        if (dtype == at::kInt) {
            // For int32, use torch fallback (integer pow with overflow semantics)
            auto res = torch::_foreach_pow(x1[i], x2[i]);
            output.copy_(res[0]);
        } else if (dtype == at::kBFloat16) {
            // For bfloat16, convert to float32, run kernel, convert back
            auto base_fp32 = x1[i].to(at::kFloat);
            auto exp_fp32 = x2[i].to(at::kFloat);
            auto out_fp32 = at::empty_like(base_fp32);
            foreach_pow_list_tensor_fp(base_fp32, exp_fp32, out_fp32);
            output.copy_(out_fp32.to(at::kBFloat16));
        } else if (dtype == at::kHalf || dtype == at::kFloat) {
            // For float16 and float32, use AscendC kernel directly
            foreach_pow_list_tensor_fp(x1[i], x2[i], output);
        } else {
            TORCH_CHECK(false, "foreach_pow_list: unsupported dtype ", dtype);
        }

        out.push_back(output);
    }

    return out;
}

}  // namespace ascend_kernel
